const btnPhoneOpen=document.querySelector(".header__btn-phone"),modalPhone=document.getElementById("modal");btnPhoneOpen.addEventListener("click",()=>{modalPhone.showModal()}),modalPhone.addEventListener("click",e=>{e.target===modalPhone&&modalPhone.close()});const btnDiscountOpen=document.querySelectorAll(".discount-btn"),modalDiscount=document.querySelector(".modal-discount");btnDiscountOpen.forEach(function(e){e.addEventListener("click",()=>{modalDiscount.showModal()}),modalDiscount.addEventListener("click",e=>{e.target===modalDiscount&&modalDiscount.close()})});const programItem=document.querySelectorAll(".program__item"),modalProgram=document.querySelector(".modal-program");let imgFiles=document.querySelectorAll(".modal-program__img-title");programItem.forEach(e=>{e.addEventListener("click",()=>{let o=e.getAttribute("id");imgFiles.forEach(e=>{imgFile=e.getAttribute("src")}),imgFile=`images/modal/${o}.svg`,document.querySelector(".modal-program__img-title").setAttribute("src",`../${imgFile}`),console.log(),console.log(o),modalProgram.showModal()}),modalProgram.addEventListener("click",e=>{e.target===modalProgram&&modalProgram.close()})});